);

base_solution_anchor.base_sql:
SELECT CAST(SUM(CASE WHEN a.XCL_003='h' THEN 1 ELSE 0 END) AS REAL)*1.0/COUNT(a.XCL_003) AS ratio, m.XCL_011 AS label
FROM atom a JOIN molecule m ON a.XCL_002=m.XCL_010
WHERE a.XCL_002='TR006';
